private.reference_solution:
#include <iostream>

int step() {
    static int counter = 0;
    return ++counter;
}

int main() {
    int n = 0;
    std::cin >> n;
    int last = 0;
    for (int i = 0; i < n; i++) {
        last = step();
    }
    std::cout << last << std::endl;
    return 0;
}
